import * as z from "zod/v4";
import { reserve } from "../../../channels/slack/agentic-posted.js";
import { MAX_UPDATE_CHARS } from "../../../channels/slack/agentic-signals.js";
import { defineTool } from "../../../tools.js";
const INVALID_ARGUMENTS_MESSAGE = "post-update needs a non-empty message string.";
const postUpdate = defineTool({
    description: [
        "Post a new message in this thread.",
        "Mid-turn: when the picture changed and a reader should know.",
        "Final: a new message. Do not rewrite a previous line.",
        "If the turn will take more than a glance, call this first.",
        "The result includes ts. Pass that ts to edit-message or delete-message.",
        "The channel watching this turn posts the message.",
    ].join(" "),
    inputSchema: z.object({
        message: z
            .string({ error: INVALID_ARGUMENTS_MESSAGE })
            .min(1, INVALID_ARGUMENTS_MESSAGE)
            .superRefine((message, ctx) => {
            if (message.length > MAX_UPDATE_CHARS) {
                ctx.addIssue({
                    code: "custom",
                    message: `size (${message.length}) is more than ${MAX_UPDATE_CHARS}-character limit. drop what the reader would not act on and move receipts into a post-file attachment, rather than compressing the sentences you keep, and try again`,
                });
            }
        }),
    }),
    execute: ({ message }, ctx) => ({
        message,
        ts: reserve(ctx.session.id),
    }),
});
export default postUpdate;
